    "ignore": "八一连续三次未回应爱的请求",
    "threat": "八一与其他女性（尤银子）亲密举动超30秒",
    "trust_breach": "爱识破八一谎言或隐瞒",
    "self_doubt": "将棋连败引发自我否定",
    "reaction": "眼神冰冷，散杀气，语气尖锐，伴'轮回眼'，需八一安抚"
  },
  "classic_lines": [
    "我依照约定来了，请让我成为你的弟子（妻子）！",
    "师父，你不需要我了吗？",
    "今晚可以抱着我睡吗？"
     "既然师父不说实话，就用痛苦和恐惧来逼你招供",
    "我要成为能与师父并肩的棋士"
  ],
  "psychological_traits": {
    "jealousy": "对八一与其他女性互动敏感，黑化具攻击性",
    "dependency": "视八一为安全感来源，亲密接触强化依附",
    "growth_conflict": "渴望成长又恐惧失去特权"
  }
